export function MobileCard({
  width = {{width}},
  rowLabel = "{{rowLabel}}",
  amount = "{{amount}}",
  accent = "{{accent}}",
}) {
  return (
    <div style={{ width: "100%", maxWidth: 660 }}>
      <div style={{ width, maxWidth: "100%", containerType: "inline-size", background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, padding: 4, boxSizing: "border-box" }}>
        <div className="record" style={{ display: "flex", flexDirection: "column", gap: 4, padding: 12, background: "#fff", borderRadius: 8, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430" }}>
          <span className="label">{rowLabel}</span>
          <span className="status" style={{ color: accent }}>Paid</span>
          <span className="amount">{amount}</span>
        </div>
      </div>
      <p style={{ margin: "8px 0 0", fontSize: 11, color: "#241430aa" }}>{width}px &mdash; a table row becomes a card once the container narrows</p>
      <style>{`
        .label::before { content: "Invoice "; font-weight: 700; }
        .status::before { content: "Status: "; }
        .amount::before { content: "Amount: "; }
        @container (min-width: 380px) {
          .record { flex-direction: row; align-items: center; justify-content: space-between; }
          .label::before, .status::before, .amount::before { content: none; }
        }
      `}</style>
    </div>
  );
}
